TriggerOraclev10g.body:
DECLARE
  v_anteriores CLOB;
  v_nuevos     CLOB;
BEGIN
  IF UPDATING OR DELETING THEN
    SELECT JSON_OBJECT('ID_EJEMPLAR' VALUE :OLD.ID_EJEMPLAR, 'ID_LIBRO' VALUE :OLD.ID_LIBRO, 'CODIGO_BARRAS' VALUE :OLD.CODIGO_BARRAS, 'ESTADO' VALUE :OLD.ESTADO, 'FECHA_ADQUISICION' VALUE :OLD.FECHA_ADQUISICION) INTO v_anteriores FROM dual;
  END IF;
  IF INSERTING OR UPDATING THEN
    SELECT JSON_OBJECT('ID_EJEMPLAR' VALUE :NEW.ID_EJEMPLAR, 'ID_LIBRO' VALUE :NEW.ID_LIBRO, 'CODIGO_BARRAS' VALUE :NEW.CODIGO_BARRAS, 'ESTADO' VALUE :NEW.ESTADO, 'FECHA_ADQUISICION' VALUE :NEW.FECHA_ADQUISICION) INTO v_nuevos FROM dual;
  END IF;
  SP_REGISTRAR_BITACORA(
    'EJEMPLAR',
    CASE WHEN INSERTING THEN 'INSERT' WHEN UPDATING THEN 'UPDATE' ELSE 'DELETE' END,
    NVL(:NEW.ID_EJEMPLAR, :OLD.ID_EJEMPLAR),
    v_anteriores,
    v_nuevos
  );
END;
